74	    /** The sheet's claims, newest first by their place in the list. */
75	    @Transactional(readOnly = true)
76	    public List<Claim> list(String sheetId) {
77	        return claims.findBySheetIdOrderByListedDesc(sheetId);
78	    }
79	
80	    /** The terms a claim of the person dated on the date is due by: the person's own, else those of their
81	     *  grade in force on the date, else the sheet's in force on the date. */
82	    private int termsOf(String sheetId, Person person, LocalDate date) {
83	        return person.getTerms() != null ? person.getTerms() : settings.terms(sheetId, person.gradeOn(date), date);
84	    }
