123	    /** Open a claim's editor for the user: the claim is locked for other users until the editor is saved
124	     *  or cancelled, or the sheet's today changes. Refused, taking no lock, for a claim that cannot be
125	     *  edited (dated inside a closed period, or not a DRAFT) and a claim locked by another user. */
126	    @Transactional
127	    public Claim lock(String sheetId, String user, long id) {
128	        Claim claim = claims.findForUpdate(id, sheetId)
129	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
130	        refuseIfClosed(sheetId, claim.getDueBy());
131	        refuseUnlessDraft(claim);
132	        refuseIfLocked(claim, user);
133	        claim.lockFor(user);
134	        return claims.saveAndFlush(claim);
135	    }
