137	    /** Close the user's editor of a claim without saving it, releasing the user's lock on it; a lock
138	     *  of another user, or none, is left as it is. */
139	    @Transactional
140	    public Claim unlock(String sheetId, String user, long id) {
141	        Claim claim = claims.findForUpdate(id, sheetId)
142	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
143	        if (user.equals(claim.getLockedBy())) claim.lockFor(null);
144	        return claims.saveAndFlush(claim);
145	    }
