147	    /** Once a holiday is added to the sheet, the due-by of every claim neither SETTLED nor VOID whose
148	     *  due-by is on or after the holiday is worked out again: the terms-th business day after the claim's
149	     *  date, with the terms the claim was fixed with, past the holidays now. */
150	    @EventListener
151	    @Transactional
152	    public void moveDueBys(HolidaysChanged change) {
153	        String sheetId = change.sheetId();
154	        Set<LocalDate> days = holidays.dates(sheetId);
155	        Rollup.Snapshot before = rollup.snapshot(sheetId);
156	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
157	            if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) continue;
158	            if (claim.getDueBy().isBefore(change.date())) continue;
159	            if (claim.moveDueBy(BusinessDays.after(claim.getDate(), claim.getTerms(), days))) {
160	                claims.save(claim);
161	            }
162	        }
163	        claims.flush();
164	        rollup.recordChanges(change.user(), before);
165	    }
