174	    private static void refuseUnlessDraft(Claim claim) {
175	        if (claim.getStatus() != ClaimStatus.DRAFT) {
176	            throw new ResponseStatusException(HttpStatus.CONFLICT,
177	                    "A " + claim.getStatus() + " claim cannot be edited; only a DRAFT can.");
178	        }
179	    }
