181	    /** Refuse a change to a claim whose editor another user has open. */
182	    private static void refuseIfLocked(Claim claim, String user) {
183	        if (claim.isLockedAgainst(user)) {
184	            throw new ResponseStatusException(HttpStatus.LOCKED,
185	                    "The claim is being edited by " + claim.getLockedBy() + ".");
186	        }
187	    }
