189	    /** Change a draft claim's amount, date and note; a blank date takes the sheet's today. A claim that
190	     *  is no longer a draft is refused: to change an open claim, void it and add a new one. A claim
191	     *  another user's editor locks is refused; saving releases the user's own lock. A new date whose
192	     *  due-by, as a claim added on it would be fixed, falls inside a closed period is refused; the
193	     *  claim's own due-by stays as it was fixed. */
194	    @Transactional
195	    public Claim update(String sheetId, String user, long id, BigDecimal amount, LocalDate date, String note,
196	            String corrects, String ref, String tags) {
197	        Claim claim = claims.findForUpdate(id, sheetId)
198	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
199	        LocalDate dated = dateOr(sheetId, date);
200	        refuseIfClosed(sheetId, claim.getDueBy());
201	        refuseUnlessDraft(claim);
202	        refuseIfLocked(claim, user);
203	        Person person = person(sheetId, claim.getPersonId());
204	        refuseIfRetired(person, dated);
205	        if (!dated.equals(claim.getDate())) {
206	            refuseIfClosed(sheetId, holidays.dueBy(sheetId, dated, termsOf(sheetId, person, dated)));
207	        }
208	        refuseIfNotCorrecting(sheetId, claim.getPersonId(), amount, corrects);
209	        String reference = refOf(ref);
210	        refuseIfRefUsed(sheetId, reference, claim.getId());
211	        Rollup.Snapshot before = rollup.snapshot(sheetId);
212	        claim.set(amount, dated, noteOf(note), corrects);
213	        claim.setRef(reference);
214	        List<String> tagged = tagsOf(tags);
215	        claim.setTags(tagged);
216	        useTags(sheetId, tagged);
217	        claim.lockFor(null);
218	        claim.setEditedBy(user);
219	        Claim saved = claims.saveAndFlush(claim);
220	        recordChange("CLAIM_EDITED", user, person(sheetId, saved.getPersonId()), saved);
221	        rollup.recordChanges(user, before);
222	        return saved;
223	    }
