225	    /** Move a claim to a new status; a change its status does not allow is refused, as is settling
226	     *  by the user who opened or last edited the claim, and an action the sheet's permission matrix does
227	     *  not allow the user's role. A clerk's settling of a claim whose due is above the sheet's
228	     *  clerk limit leaves it PENDING for a steward to approve (a due of n/a is within any limit; a
229	     *  steward settles anything). */
230	    @Transactional
231	    public Claim changeStatus(String sheetId, String user, long id, ClaimStatus next) {
232	        return changeStatus(sheetId, user, id, next, null);
233	    }
