235	    /** Make the claims a bulk settle settled (or left pending) the sheet's next settle batch: each shows
236	     *  its number. Its audit line, after the claims' own, carries the batch's number, how many claims it
237	     *  has and the frozen dues of those SETTLED added up. Returns the batch's number. */
238	    @Transactional
239	    public int markSettleBatch(String sheetId, String user, List<Claim> settled) {
240	        int batch = sheets.nextSettleBatch(sheetId);
241	        BigDecimal total = BigDecimal.ZERO.setScale(2);
242	        for (Claim claim : settled) {
243	            Claim row = claims.findForUpdate(claim.getId(), sheetId).orElseThrow();
244	            row.setSettleBatch(batch);
245	            claims.save(row);
246	            claim.setSettleBatch(batch);
247	            if (claim.getStatus() == ClaimStatus.SETTLED && claim.getSettledDue() != null) {
248	                total = total.add(claim.getSettledDue());
249	            }
250	        }
251	        claims.flush();
252	        audit.recordOnCommit("BATCH_SETTLED sheet=" + sheetId + " by=" + user + " batch=" + batch
253	                + " count=" + settled.size() + " total=" + total.toPlainString());
254	        return batch;
255	    }
256	
257	    /** Void a claim, as {@link #changeStatus}; while the sheet has void reasons, a void without one of
258	     *  them is refused. The reason is kept on the claim and ends its audit line. */
259	    @Transactional
260	    public Claim voidClaim(String sheetId, String user, long id, String reason) {
261	        return changeStatus(sheetId, user, id, ClaimStatus.VOID, reason);
262	    }
263	
264	    private Claim changeStatus(String sheetId, String user, long id, ClaimStatus next, String reason) {
265	        Claim claim = claims.findForUpdate(id, sheetId)
266	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
267	        refuseIfClosed(sheetId, claim.getDueBy());
268	        boolean voidingSettled = next == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED;
269	        if (voidingSettled) {
270	            refuseUnlessSettledVoidable(sheetId, user, claim);
271	        } else if (!claim.getStatus().canBecome(next)) {
272	            throw new ResponseStatusException(HttpStatus.CONFLICT,
273	                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
274	        } else {
275	            settings.refuseUnlessPermitted(sheetId, user, ACTIONS.get(next),
276	                    "Your role may not " + ACTIONS.get(next) + " a claim on this sheet.");
277	        }
278	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
279	            throw new ResponseStatusException(HttpStatus.CONFLICT,
280	                    "The claim is deferred until " + claim.getDeferredUntil() + " and cannot be settled before then.");
281	        }
282	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
283	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
284	                    "The user who opened a claim cannot settle it.");
285	        }
286	        if (next == ClaimStatus.SETTLED && user.equals(claim.getEditedBy())) {
287	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
288	                    "The user who last edited a claim cannot settle it.");
289	        }
290	        String voidReason = next == ClaimStatus.VOID ? voidReasons.reasonToVoid(sheetId, reason) : null;
291	        Person person = person(sheetId, claim.getPersonId());
292	        // Worked out while the claim is still open: settling freezes the due, its late charge included.
293	        BigDecimal dueNow = next == ClaimStatus.SETTLED ? due(sheetId, person, claim) : null;
294	        if (next == ClaimStatus.SETTLED) refuseIfUnproven(sheetId, person, claim, dueNow);
295	        if (next == ClaimStatus.OPEN) refuseIfUnnoted(sheetId, claim, due(sheetId, person, claim));
296	        // Settled one at a time until a bulk settle marks it with its batch.
297	        if (next == ClaimStatus.SETTLED) claim.setSettleBatch(null);
298	        if (next == ClaimStatus.SETTLED && isAboveClerkLimit(sheetId, user, dueNow)) next = ClaimStatus.PENDING;
299	        Rollup.Snapshot before = rollup.snapshot(sheetId);
300	        String number = next == ClaimStatus.OPEN ? nextNumber(sheetId, claim) : claim.getNumber();
301	        claim.setStatus(next);
302	        if (next == ClaimStatus.OPEN) claim.setOpenedBy(user);
303	        // A voided claim keeps its number, which is never given to another claim.
304	        claim.setNumber(number);
305	        if (next == ClaimStatus.SETTLED) claim.setSettledDue(dueNow);
306	        if (next == ClaimStatus.VOID) claim.setVoidReason(voidReason);
307	        logStatus(sheetId, user, person, claim);
308	        Claim saved = claims.saveAndFlush(claim);
309	        String event = EVENTS.get(next);
310	        if (next == ClaimStatus.SETTLED) {
311	            recordChange(event, user, person, saved, number, " due=" + text(saved.getSettledDue()));
312	            notifyWatchers(user, person, saved);
313	        } else if (voidingSettled) {
314	            recordChange(event, user, person, saved, number, " reversed=" + text(saved.getSettledDue())
315	                    + reasonField(voidReason));
316	        } else {
317	            recordChange(event, user, person, saved, number, reasonField(voidReason));
318	        }
319	        rollup.recordChanges(user, before);
320	        return saved;
321	    }
322	
323	    /** Defer an OPEN claim until a date after the sheet's today: until the sheet's today reaches it the
324	     *  claim counts in no total, is not overdue, cannot be settled and no statement binds it. Refused for
325	     *  a claim that is not OPEN, a date not after today, and a claim dated inside a closed period. */
326	    @Transactional
327	    public Claim defer(String sheetId, String user, long id, LocalDate until) {
328	        Claim claim = claims.findForUpdate(id, sheetId)
329	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
330	        refuseIfClosed(sheetId, claim.getDueBy());
331	        if (claim.getStatus() != ClaimStatus.OPEN) {
332	            throw new ResponseStatusException(HttpStatus.CONFLICT,
333	                    "A " + claim.getStatus() + " claim cannot be deferred; only an OPEN one can.");
334	        }
335	        if (!until.isAfter(sheets.today(sheetId))) {
336	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
337	                    "A claim can only be deferred to a date after the sheet's today.");
338	        }
339	        Person person = person(sheetId, claim.getPersonId());
340	        Rollup.Snapshot before = rollup.snapshot(sheetId);
341	        claim.deferUntil(until);
342	        Claim saved = claims.saveAndFlush(claim);
343	        recordChange("CLAIM_DEFERRED", user, person, saved, saved.getNumber(), " until=" + until);
344	        rollup.recordChanges(user, before);
345	        return saved;
