348	    /** Split an amount (more than 0.00 and less than the claim's amount) off an OPEN claim into a new
349	     *  OPEN claim of the same person, date and note, given the next number, opened by the user and due
350	     *  by the terms in force on the date; the claim keeps the rest and loses any figure a statement bound
351	     *  it to; it is a late entry when its due-by falls inside a soft-closed period. Refused for a claim that
352	     *  is not OPEN (a PENDING one included), a deferred claim, and a claim whose due-by, or the new claim's,
353	     *  is inside a closed period. */
354	    @Transactional
355	    public Split split(String sheetId, String user, long id, BigDecimal part) {
356	        Claim claim = claims.findForUpdate(id, sheetId)
357	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
358	        refuseIfClosed(sheetId, claim.getDueBy());
359	        if (claim.getStatus() != ClaimStatus.OPEN) {
360	            throw new ResponseStatusException(HttpStatus.CONFLICT,
361	                    "A " + claim.getStatus() + " claim cannot be split; only an OPEN one can.");
362	        }
363	        if (claim.isDeferredOn(sheets.today(sheetId))) {
364	            throw new ResponseStatusException(HttpStatus.CONFLICT,
365	                    "The claim is deferred until " + claim.getDeferredUntil() + " and cannot be split.");
366	        }
367	        if (part.signum() <= 0 || part.compareTo(claim.getAmount()) >= 0) {
368	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
369	                    "The amount split off must be more than 0.00 and less than the claim's amount.");
370	        }
371	        Person person = person(sheetId, claim.getPersonId());
372	        // The terms are fixed now, those in force on the claim's date; the due-by counts them in business days.
373	        int terms = termsOf(sheetId, person, claim.getDate());
374	        LocalDate dueBy = holidays.dueBy(sheetId, claim.getDate(), terms);
375	        refuseIfClosed(sheetId, dueBy);
376	        Rollup.Snapshot before = rollup.snapshot(sheetId);
377	        Claim split = claim.splitOff(part, null, user, terms, dueBy, sheets.today(sheetId));
378	        String number = nextNumber(sheetId, split);
379	        split.setNumber(number);
380	        // Split off into a soft-closed period, the new claim is a late entry of it.
381	        if (periods.isSoftClosedOn(sheetId, dueBy)) split.markLateEntry();
382	        split.setListed(claims.lastListed(sheetId) + 1);
383	        Claim saved = claims.saveAndFlush(claim);
384	        split = claims.saveAndFlush(split);
385	        logStatus(sheetId, user, person, split);
386	        recordChange("CLAIM_SPLIT", user, person, saved, saved.getNumber(), " into=" + number);
387	        recordChange("CLAIM_OPENED", user, person, split);
388	        rollup.recordChanges(user, before);
389	        return new Split(saved, split);
390	    }
