492	    /** Move a claim as {@link #reassign(String, String, long, long)} does; a claim moved with others to
493	     *  its own person is not refused but re-listed as that person's newest claim. */
494	    @Transactional
495	    public Claim reassign(String sheetId, String user, long id, long toPersonId, boolean withOthers) {
496	        Claim claim = claims.findForUpdate(id, sheetId)
497	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
498	        refuseIfClosed(sheetId, claim.getDueBy());
499	        settings.refuseUnlessPermitted(sheetId, user, "reassign",
500	                "Your role may not move a claim to another person on this sheet.");
501	        if (claim.getStatus() != ClaimStatus.DRAFT && !claim.getStatus().isOpen()) {
502	            throw new ResponseStatusException(HttpStatus.CONFLICT,
503	                    "A " + claim.getStatus() + " claim cannot be moved to another person.");
504	        }
505	        Person from = person(sheetId, claim.getPersonId());
506	        Person to = person(sheetId, toPersonId);
507	        if (!withOthers && from.getId().equals(to.getId())) {
508	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is already " + to.getName() + "'s.");
509	        }
510	        refuseIfRetired(to, claim.getDate());
511	        Rollup.Snapshot before = rollup.snapshot(sheetId);
512	        claim.moveTo(to.getId(), claims.lastListed(sheetId) + 1, sheets.today(sheetId));
513	        // Moved to another person, a numbered claim takes the next number; its old one is not reused.
514	        if (claim.getNumber() != null && !from.getId().equals(to.getId())) {
515	            claim.setNumber(nextNumber(sheetId, claim));
516	        }
517	        Claim saved = claims.saveAndFlush(claim);
518	        recordChange("CLAIM_REASSIGNED", user, to, saved, saved.getNumber(),
519	                " from=" + from.getName() + " to=" + to.getName());
520	        rollup.recordChanges(user, before);
521	        return saved;
522	    }
