524	    /** Approve a PENDING claim: it is SETTLED, its due (its live figure and any late charge) frozen
525	     *  now. Refused unless the user is a steward of the sheet other than the one who opened or last
526	     *  edited it. */
527	    @Transactional
528	    public Claim approve(String sheetId, String user, long id) {
529	        Claim claim = pending(sheetId, user, id);
530	        if (user.equals(claim.getOpenedBy())) {
531	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
532	                    "The user who opened a claim cannot approve it.");
533	        }
534	        if (user.equals(claim.getEditedBy())) {
535	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
536	                    "The user who last edited a claim cannot approve it.");
537	        }
538	        Person person = person(sheetId, claim.getPersonId());
539	        BigDecimal dueNow = due(sheetId, person, claim);
540	        refuseIfUnproven(sheetId, person, claim, dueNow);
541	        Rollup.Snapshot before = rollup.snapshot(sheetId);
542	        claim.setStatus(ClaimStatus.SETTLED);
543	        claim.setSettledDue(dueNow);
544	        logStatus(sheetId, user, person, claim);
545	        Claim saved = claims.saveAndFlush(claim);
546	        recordChange("CLAIM_APPROVED", user, person, saved, saved.getNumber(), " due=" + text(saved.getSettledDue()));
547	        notifyWatchers(user, person, saved);
548	        rollup.recordChanges(user, before);
549	        return saved;
550	    }
