552	    /** Re-settle a SETTLED claim: its due is frozen again at what it would be today as an open claim
553	     *  bound by no statement (today's rates, grades, floor and late charge). Refused unless the user is
554	     *  a steward of the sheet, and for a claim that is not SETTLED or is dated inside a closed period. */
555	    @Transactional
556	    public Claim resettle(String sheetId, String user, long id) {
557	        Claim claim = claims.findForUpdate(id, sheetId)
558	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
559	        refuseIfClosed(sheetId, claim.getDueBy());
560	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
561	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward re-settles a claim.");
562	        }
563	        if (claim.getStatus() != ClaimStatus.SETTLED) {
564	            throw new ResponseStatusException(HttpStatus.CONFLICT,
565	                    "A " + claim.getStatus() + " claim cannot be re-settled; only a SETTLED one can.");
566	        }
567	        Person person = person(sheetId, claim.getPersonId());
568	        BigDecimal old = claim.getSettledDue();
569	        BigDecimal dueNow = LateCharge.dueAsOpen(claim, dueNow(sheetId, person, claim),
570	                settings.floor(sheetId, claim.getDate()), sheets.today(sheetId), grace(sheetId, person, claim),
571	                settings.dated(sheetId)::latePctOn, rounding(sheetId, claim));
