575	        Claim saved = claims.saveAndFlush(claim);
576	        recordChange("CLAIM_RESETTLED", user, person, saved, saved.getNumber(),
577	                " old=" + text(old) + " new=" + text(saved.getSettledDue()));
578	        notifyWatchers(user, person, saved);
579	        rollup.recordChanges(user, before);
580	        return saved;
581	    }
