617	    /** Refuse voiding a SETTLED claim unless the user is a steward of the sheet and the sheet's today is
618	     *  within {@value #VOID_SETTLED_DAYS} days of the claim's settlement, as its status log records it. */
619	    private void refuseUnlessSettledVoidable(String sheetId, String user, Claim claim) {
620	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
