668	    /** Refuse settling or approving a claim with no proofs whose due is above the proof threshold in force
669	     *  on the claim's date: its person's grade's then when one is set, else the sheet's (a due of n/a, or
670	     *  no threshold, needs none). */
671	    private void refuseIfUnproven(String sheetId, Person person, Claim claim, BigDecimal due) {
672	        if (due == null || claim.getProofs() > 0) return;
673	        BigDecimal threshold = settings.proofThreshold(sheetId, person.gradeOn(claim.getDate()), claim.getDate());
674	        if (threshold != null && due.compareTo(threshold) > 0) {
675	            throw new ResponseStatusException(HttpStatus.CONFLICT,
676	                    "The claim's due is above the proof threshold of " + threshold.toPlainString()
677	                            + "; add a proof before it is settled.");
678	        }
