683	    private void refuseIfUnnoted(String sheetId, Claim claim, BigDecimal due) {
684	        if (due == null || (claim.getNote() != null && !claim.getNote().isBlank())) return;
685	        BigDecimal threshold = settings.noteThreshold(sheetId, claim.getDate());
