756	    /** The figure under the claim's due, before any late charge and floor: the due fixed when it was settled, else the figure
757	     *  its person's last statement bound it to (unless it is PENDING, which no statement binds), else its live due;
758	     *  null when that is n/a. */
759	    public BigDecimal figure(String sheetId, Person person, Claim claim) {
760	        if (claim.getSettledDue() != null) return claim.getSettledDue();
761	        if (claim.isBound()) return claim.getStatedDue();
762	        return dueNow(sheetId, person, claim);
763	    }
764	
765	    /** The claim's rate figure now: at the rate in force on the claim's date of its person's grade in
766	     *  force on that date, rounded as the claim's {@link Rounding} decides, before any late charge and
767	     *  floor; null when no rate of the grade applies by then. */
768	    private BigDecimal dueNow(String sheetId, Person person, Claim claim) {
769	        Rate rate = rates.inForce(sheetId, person.gradeOn(claim.getDate()), claim.getDate());
770	        if (rate == null) return null;
771	        return claim.getAmount().multiply(rate.getPct()).divide(BigDecimal.valueOf(100), 2,
772	                rounding(sheetId, claim));
773	    }
774	
775	    /** How many claims a candidate rate would change and by how much in all. */
776	    public record RatePreview(int count, BigDecimal diff) {
777	    }
778	
779	    /** What a candidate percent for a grade, applied on every date, would do to the OPEN and PENDING claims of
780	     *  people on that grade on the claim's date: how many would show a different due, and the sum of new due
781	     *  less current due (an n/a due counting as 0.00). A claim bound by a statement does not change; nothing is saved. */
782	    @Transactional(readOnly = true)
783	    public RatePreview previewRate(String sheetId, Grade grade, BigDecimal pct) {
784	        Map<Long, Person> byId = new HashMap<>();
785	        for (Person p : people.findBySheetIdOrderByIdAsc(sheetId)) byId.put(p.getId(), p);
786	        int count = 0;
787	        BigDecimal diff = BigDecimal.ZERO.setScale(2);
788	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
789	            if (!claim.getStatus().isOpen() || claim.isBound() || claim.getSettledDue() != null) continue;
790	            Person person = byId.get(claim.getPersonId());
791	            if (person == null || person.gradeOn(claim.getDate()) != grade) continue;
792	            RoundingMode rounding = rounding(sheetId, claim);
793	            BigDecimal figure = claim.getAmount().multiply(pct).divide(BigDecimal.valueOf(100), 2, rounding);
794	            BigDecimal next = LateCharge.dueOf(claim, figure, settings.floor(sheetId, claim.getDate()),
795	                    sheets.today(sheetId), grace(sheetId, person, claim), settings.dated(sheetId)::latePctOn, rounding);
796	            BigDecimal current = due(sheetId, person, claim);
797	            if (current != null && current.compareTo(next) == 0) continue;
798	            count++;
799	            diff = diff.add(next.subtract(current == null ? BigDecimal.ZERO : current));
800	        }
801	        return new RatePreview(count, diff.setScale(2));
802	    }
803	
804	    /** How the claim's live figures round under the sheet's policy date: by the date of the claim a
805	     *  correction corrects, else by its own. */
806	    private RoundingMode rounding(String sheetId, Claim claim) {
807	        return rounding(sheetId, claim, sheets.today(sheetId));
808	    }
809	
810	    /** How the claim's figures round under the sheet's policy date with the date given standing in for
811	     *  the sheet's today. */
812	    public RoundingMode rounding(String sheetId, Claim claim, LocalDate today) {
813	        Claim corrected = claim.isCorrection() && claim.getCorrects() != null
814	                ? claims.findBySheetIdAndPersonIdAndNumber(sheetId, claim.getPersonId(), claim.getCorrects()).orElse(null)
815	                : null;
816	        return Rounding.of(Rounding.dateOf(claim, corrected),
817	                Rounding.policyDate(settings.policyDate(sheetId), today));
818	    }
819	
820	    /** The audit field of the reason a claim was voided with; blank when there is none. */
821	    private static String reasonField(String voidReason) {
822	        return voidReason == null ? "" : " reason=" + voidReason;
823	    }
824	
825	    /** Log the status the claim has just taken, with its due as worked out now. */
826	    private void logStatus(String sheetId, String user, Person person, Claim claim) {
827	        claim.logStatus(user, sheets.today(sheetId), due(sheetId, person, claim));
828	    }
829	
830	    private void recordChange(String event, String user, Person person, Claim claim) {
831	        recordChange(event, user, person, claim, claim.getNumber(), "");
832	    }
833	
834	    /** The claim's audit line; a claim with a number carries it, then any extra fields. */
835	    private void recordChange(String event, String user, Person person, Claim claim, String number, String extra) {
836	        audit.recordOnCommit(event + " sheet=" + claim.getSheetId() + " by=" + user + " person=" + person.getName()
837	                + " amount=" + claim.getAmount().toPlainString() + " date=" + claim.getDate()
838	                + (number == null ? "" : " number=" + number) + extra);
839	    }
840	
841	    /** Tell each user watching the person, in the order they started watching, that the claim was settled. */
842	    private void notifyWatchers(String user, Person person, Claim claim) {
843	        for (PersonWatch watch : watches.findByPersonIdOrderByIdAsc(person.getId())) {
844	            audit.recordOnCommit("NOTIFY sheet=" + claim.getSheetId() + " by=" + user + " user=" + watch.getUserName()
845	                    + " person=" + person.getName() + " number=" + claim.getNumber());
846	        }
847	    }
848	
849	    private LocalDate dateOr(String sheetId, LocalDate date) {
850	        return date != null ? date : sheets.today(sheetId);
851	    }
852	
853	    /** The date a new claim given none takes: the sheet's entry date while it is set, else its today. */
854	    private LocalDate entryDateOr(String sheetId) {
855	        LocalDate entry = settings.entryDate(sheetId);
856	        return entry != null ? entry : sheets.today(sheetId);
857	    }
858	
859	    /** Every tag ever used on the sheet, by name. */
860	    @Transactional(readOnly = true)
861	    public List<String> tags(String sheetId) {
862	        return sheetTags.findBySheetIdOrderByNameAsc(sheetId).stream().map(SheetTag::getName).toList();
863	    }
864	
865	    /** Keep the tags as used on the sheet. */
866	    public void useTags(String sheetId, List<String> tagged) {
867	        for (String tag : tagged) {
868	            if (!sheetTags.existsBySheetIdAndName(sheetId, tag)) sheetTags.save(new SheetTag(sheetId, tag));
869	        }
870	    }
871	
872	    /** Tags as typed, comma separated: each trimmed and lower-cased, blanks and repeats dropped, sorted. */
873	    public static List<String> tagsOf(String tags) {
874	        if (tags == null) return List.of();
875	        return Arrays.stream(tags.split(",")).map(t -> t.trim().toLowerCase(Locale.ROOT)).filter(t -> !t.isEmpty())
876	                .distinct().sorted().toList();
877	    }
878	
879	    /** A reference as given, trimmed; none when blank. */
880	    public static String refOf(String ref) {
881	        return ref == null || ref.isBlank() ? null : ref.trim();
882	    }
883	
884	    private static String noteOf(String note) {
885	        return note == null ? "" : note.trim();
886	    }
887	}
